scripts.杨影枫对话.txt:
	If ($Event == 302) @Label1;
	If ($Event == 340) @Label2;

	Goto @end;

@Label1:
	If ($Talkyyf053 == 0) @Talk0;
	If ($Talkyyf053 == 1) @Talk1;
	Goto @end;
@Talk0:
	If ($NaLanZhenSense >= 20) @AddSenseEnd;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd:
	Talk(5221, 5229);
	Talk(5231, 5233);
	Assign($Talkyyf053, 1);
	Goto @end;
@Talk1:
	If ($NaLanZhenSense >= 20) @AddSenseEnd1;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd1:
	Say("杨影枫：真儿，你从小就生活在忘忧岛上吗？", 2);
	Say("纳兰真：是啊，从出生到现在，我从来没有离开过忘忧岛，爹说外面的世界太复杂，还是不要出去的好。", 9);
	Goto @end;

	
@Label2:
	If ($NaLanZhenSense >= 20) @AddSenseEnd2;
	Add($SenseVal, 5);
	Add($NaLanZhenSense, 5);
@AddSenseEnd2:
	Talk(5948, 5949);
	Goto @end;

@end:
	Return;

